class Counter {
    public int Raw = 10;
    public int Value {
        get { Print("get"); return Raw; }
        set { Print("set:" + value); Raw = value * 2; value = 99; return; }
    }
}
Counter Get(Counter c) { Print("receiver"); return c; }
int Change(Counter c) { Print("rhs"); c.Raw = 1; return 3; }
void Main() {
    var c = new Counter();
    Print(Get(c).Value += Change(c)); Print(c.Raw);
    Print(Get(c).Value++); Print(c.Raw);
    Print(++Get(c).Value); Print(c.Raw);
    Print(Get(c).Value = 4); Print(c.Raw);
}
